import credits from '@/data/photo-credits.json'

/** A Wikimedia Commons photo (attribution + licence). */
export interface CommonsCredit {
  vehicleId: string
  type?: 'commons'
  fileTitle: string
  author: string
  licenseName: string
  licenseUrl: string
  sourceUrl: string
  modified: boolean
}

/** An illustration generated by an AI image model – no licence, not a photo of the real car. */
export interface AiCredit {
  vehicleId: string
  type: 'ai-generated'
  author: string
}

export type PhotoCredit = CommonsCredit | AiCredit

export const photoCredits = credits as PhotoCredit[]

export const isAiCredit = (c: PhotoCredit): c is AiCredit => c.type === 'ai-generated'

const aiIds = new Set(photoCredits.filter(isAiCredit).map((c) => c.vehicleId))

/** True when the vehicle's image is an AI-generated illustration (Symbolbild). */
export const isAiImage = (vehicleId: string) => aiIds.has(vehicleId)
